[CmdletBinding()]
param([switch]$Check)
$ErrorActionPreference='Stop';$root=git rev-parse --show-toplevel;$required=@('.agentic/agents.json','.agentic/models.json','.agentic/mcp.json','.agentic/roles/planner.md','.agentic/roles/builder.md','.agentic/roles/reviewer.md','.claude/agents/planner.md','.claude/agents/builder.md','.claude/agents/reviewer.md','.codex/prompts/planner.md','.codex/prompts/planner-agent.md','.codex/planner.md','.codex/planner.config.toml','.codex/builder.md','.codex/reviewer.md','.opencode/agent/planner.md','.opencode/agent/builder.md','.opencode/agent/reviewer.md');$missing=@($required|Where-Object{!(Test-Path (Join-Path $root $_))});if($missing){throw "Faltan fuentes/adaptadores: $($missing -join ', ')"};$agents=Get-Content (Join-Path $root '.agentic/agents.json') -Raw|ConvertFrom-Json;foreach($adapter in @('claude','codex','opencode')){if(!$agents.adapters.$adapter){throw "Adaptador no declarado: $adapter"}};foreach($pair in @(@('.claude/agents/planner.md','planner'),@('.claude/agents/builder.md','builder'),@('.claude/agents/reviewer.md','reviewer'),@('.codex/planner.md','planner'),@('.codex/builder.md','builder'),@('.codex/reviewer.md','reviewer'),@('.opencode/agent/planner.md','planner'),@('.opencode/agent/builder.md','builder'),@('.opencode/agent/reviewer.md','reviewer'))){$content=Get-Content (Join-Path $root $pair[0]) -Raw;if($content -notmatch [regex]::Escape(".agentic/roles/$($pair[1]).md")){throw "Adaptador divergente: $($pair[0])"}};$oc=Get-Content (Join-Path $root 'opencode.json') -Raw|ConvertFrom-Json;foreach($role in @('planner','builder','reviewer')){if(!$oc.agent.$role){throw "Rol no adaptado en OpenCode: $role"}};if($Check){'Agentic adapters check PASS: Claude, Codex y OpenCode declarados y coherentes'}else{'Adaptadores validados contra la fuente canonica; no se generan archivos automaticamente en esta unidad.'}
